pub fn node__base_input(dx: &mut Dx, ty: u16, args: u32, first: u32) -> Option<gpui_kit::AnyElement> {
    let el = match ty {
        320 => make_base_editor(dx, ty, args, first).map(|e| e.into_any_element()),
        330 => make_base_input(dx, ty, args, first).map(|e| e.into_any_element()),
        331 => make_base_input_base(dx, ty, args, first).map(|e| e.into_any_element()),
        413 => make_base_textarea(dx, ty, args, first).map(|e| e.into_any_element()),
        _ => return None,
    };
    Some(el.unwrap_or_else(|| gpui_kit::div().into_any_element()))
}
